const matchChargebackPayments = `-- name: MatchChargebackPayments :many
SELECT p.id AS payment_id,
       p.transaction_id AS payment_transaction_id,
       p.subscription_id AS subscription_id,
       COALESCE(sub.rail_subscription_id, '')::text AS rail_subscription_id,
       p.customer_id::text AS user_id,
       (p.amount / 10000)::bigint AS amount_cents,
       p.currency AS currency,
       p.purchased_at AS purchased_at,
       COALESCE(pm.card_last4, '')::text AS card_last4
FROM billing.payments p
LEFT JOIN billing.subscriptions sub ON sub.id = p.subscription_id
  AND sub.merchant_id = p.merchant_id AND sub.psp_id = p.psp_id
  AND sub.deleted_at IS NULL AND sub.rail::text = p.rail::text
LEFT JOIN billing.payment_methods pm ON pm.id = sub.payment_method_id
LEFT JOIN LATERAL (
  SELECT cpm.id FROM billing.payment_methods cpm
  WHERE p.subscription_id IS NULL
    AND cpm.merchant_id = p.merchant_id AND cpm.customer_id = p.customer_id AND cpm.psp_id = p.psp_id
    AND cpm.card_last4 = $1::text
  LIMIT 1) customer_card ON true
WHERE p.merchant_id = $2::uuid AND p.psp_id = $3::uuid
  AND (p.subscription_id IS NULL OR sub.id IS NOT NULL)
  AND p.refunded_payment_id IS NULL
  AND p.deleted_at IS NULL
  AND p.rail = $4::text
  AND p.amount > 0
  AND p.amount = $5::bigint * 10000
  AND (pm.card_last4 = $1::text
    OR RIGHT(regexp_replace(COALESCE(p.card_last4, ''), '[^0-9]', '', 'g'), 4) = $1::text
    OR customer_card.id IS NOT NULL)
  AND p.purchased_at >= $6::timestamptz
  AND p.purchased_at <= $7::timestamptz
ORDER BY ABS(EXTRACT(EPOCH FROM (p.purchased_at - $8::timestamptz))) ASC,
         p.purchased_at DESC
LIMIT 2
`

type MatchChargebackPaymentsParams struct {
	Last4       string
	MerchantID  uuid.UUID
	PspID       uuid.UUID
	Rail        string
	AmountCents int64
	FromAt      time.Time
	ToAt        time.Time
	TargetAt    time.Time
}

type MatchChargebackPaymentsRow struct {
	PaymentID            uuid.UUID
	PaymentTransactionID string
	SubscriptionID       *uuid.UUID
	RailSubscriptionID   string
	UserID               string
	AmountCents          int64
	Currency             string
	PurchasedAt          time.Time
	CardLast4            string
}

// NMI chargeback reconciliation (webhooks/nmi.go): candidate charges
// (subscription or one-time) matched by amount + card last4 within ±7d of the
// chargeback date, closest-in-time first. LIMIT 2 so the caller can detect ambiguity.
// A lateral probe, not EXISTS under OR, which plans as a hash of every merchant's cards.
func (q *Queries) MatchChargebackPayments(ctx context.Context, arg MatchChargebackPaymentsParams) ([]MatchChargebackPaymentsRow, error) {
	rows, err := q.db.Query(ctx, matchChargebackPayments,
		arg.Last4,
		arg.MerchantID,
		arg.PspID,
		arg.Rail,
		arg.AmountCents,
		arg.FromAt,
		arg.ToAt,
		arg.TargetAt,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MatchChargebackPaymentsRow
	for rows.Next() {
		var i MatchChargebackPaymentsRow
		if err := rows.Scan(
			&i.PaymentID,
			&i.PaymentTransactionID,
			&i.SubscriptionID,
			&i.RailSubscriptionID,
			&i.UserID,
			&i.AmountCents,
			&i.Currency,
			&i.PurchasedAt,
			&i.CardLast4,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const mergeStripePaymentMetadata = `-- name: MergeStripePaymentMetadata :exec
UPDATE billing.payments
SET metadata = COALESCE(metadata, '{}'::jsonb) || $1::jsonb
WHERE merchant_id = $2::uuid AND psp_id = $3::uuid
  AND rail = 'stripe'
  AND transaction_id = $4
  AND deleted_at IS NULL
`

type MergeStripePaymentMetadataParams struct {
	Patch         []byte
	MerchantID    uuid.UUID
	PspID         uuid.UUID
	TransactionID string
}

func (q *Queries) MergeStripePaymentMetadata(ctx context.Context, arg MergeStripePaymentMetadataParams) error {
	_, err := q.db.Exec(ctx, mergeStripePaymentMetadata,
		arg.Patch,
		arg.MerchantID,
		arg.PspID,
		arg.TransactionID,
	)
	return err
}

const recordRefundProviderReceipt = `-- name: RecordRefundProviderReceipt :exec
UPDATE billing.payments
SET metadata = COALESCE(metadata, '{}'::jsonb)
    || jsonb_build_object('provider_refund_id', $1::text)
WHERE merchant_id = $2::uuid
  AND id = $3::uuid
  AND status = 'pending'
  AND deleted_at IS NULL
`

type RecordRefundProviderReceiptParams struct {
	ProviderRefundID string
	MerchantID       uuid.UUID
	ReservationID    uuid.UUID
}

// The rail confirmed the reversal and named it, so the row now records real
// (negative) money movement (or#827).
// Capture the provider's exact success before retryable local finalization.
func (q *Queries) RecordRefundProviderReceipt(ctx context.Context, arg RecordRefundProviderReceiptParams) error {
	_, err := q.db.Exec(ctx, recordRefundProviderReceipt, arg.ProviderRefundID, arg.MerchantID, arg.ReservationID)
	return err
}

const snapshotPaymentCards = `-- name: SnapshotPaymentCards :exec
UPDATE billing.payments
SET card_brand = $1::text,
    card_last4 = $2::text
WHERE merchant_id = $3::uuid AND psp_id = $4::uuid
  AND rail = 'stripe'
  AND transaction_id = ANY($5::text[])
  AND card_last4 IS NULL
  AND deleted_at IS NULL
`

type SnapshotPaymentCardsParams struct {
	CardBrand      string
	CardLast4      string
	MerchantID     uuid.UUID
	PspID          uuid.UUID
	TransactionIds []string
}

// Backfill a card snapshot onto Stripe payments that still lack one.
func (q *Queries) SnapshotPaymentCards(ctx context.Context, arg SnapshotPaymentCardsParams) error {
	_, err := q.db.Exec(ctx, snapshotPaymentCards,
		arg.CardBrand,
		arg.CardLast4,
		arg.MerchantID,
		arg.PspID,
		arg.TransactionIds,
	)
	return err
}
